def next_permutation(perm):
    # Find the first number from the end that is smaller than the number following it
    for i in range(len(perm) - 1, -1, -1):
        if perm[i] > perm[i + 1]:
            break

    # If there is no smaller number after the last number, return False
    if i == -1:
        return False

    # Find the smallest number that is larger and comes after the first smaller number
    for j in range(len(perm) - 1, -1, -1):
        if perm[j] > perm[i] and perm[j] < perm[i + 1]:
            break

    # Swap the smallest number with the first smaller number
    perm[i], perm[j] = perm[j], perm[i]

    # Reverse the order of the numbers after the first smaller number
    perm[i + 1:] = perm[i + 1:][::-1]

    return True

